mapper.sql:
where true

  and m.created_at >= cast(#{from} as date)::timestamp at time zone #{zone}
  and m.created_at < (cast(#{to} as date) + 1)::timestamp at time zone #{zone}

  and m.hold_yn = 'Y' and hb_lot_balance(m.lot_id) > 0
  and m.item_id = #{itemId}
  and m.origin = #{origin}
  and m.wo_id = #{woId}

  and (m.lot_no like '%' || #{keyword} || '%' escape '\' or m.supplier_lot_no like '%' || #{keyword} || '%' escape '\')

mapper.select:
select 


 order by m.created_at desc, m.lot_id desc
 limit #{limit}
